screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブルインデックス: 営業活動=0, 顧客企業=1, 成約=2, ユーザー=3, 成果指標=4
  const activityTableIndex = 0;
  const customerTableIndex = 1;
  const contractTableIndex = 2;
  const userTableIndex = 3;
  const metricsTableIndex = 4;

  // 1. 再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#result-tbody");
    const countEl = container.querySelector("#result-count");

    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-top: 1px solid rgba(255,255,255,0.05);"><td colspan="7" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 13px;">該当するデータがありません</td></tr>';
      countEl.textContent = "0";
      return;
    }

    countEl.textContent = rows.length;
    tbody.innerHTML = rows.map(r => {
      const activityDate = r.活動日 ? new Date(r.活動日).toLocaleDateString('ja-JP') : '-';
      const userName = r.ユーザー名 || r.営業担当者 || '-';
      const companyName = r.顧客名 || r.企業名 || '-';
      const activityType = r.活動種別 || '-';
      const contractStatus = r.成果有無 ? '成約' : '未成約';
      const amount = r.成果金額 ? `¥${r.成果金額.toLocaleString()}` : '-';

      return `<tr style="border-top: 1px solid rgba(255,255,255,0.05); transition: background 0.2s;">
        <td style="padding: 10px 12px; color: var(--text);">${activityDate}</td>
        <td style="padding: 10px 12px; color: var(--text);">${userName}</td>
        <td style="padding: 10px 12px; color: var(--text);">${companyName}</td>
        <td style="padding: 10px 12px; color: var(--text);">${activityType}</td>
        <td style="padding: 10px 12px; color: var(--text);">
          <span style="display: inline-block; padding: 3px 8px; border-radius: 3px; font-size: 12px; font-weight: 600; ${contractStatus === '成約' ? 'background: rgba(255, 193, 7, 0.2); color: #ffc107;' : 'background: rgba(255,255,255,0.1); color: var(--text-muted);'}">${contractStatus}</span>
        </td>
        <td style="padding: 10px 12px; text-align: right; color: var(--primary); font-weight: 600;">${amount}</td>
        <td style="padding: 10px 12px; text-align: center;">
          <button class="action-btn secondary detail-btn" data-id="${r.id || r.営業活動ID}" style="padding: 4px 10px; font-size: 12px; cursor: pointer;">詳細</button>
        </td>
      </tr>`;
    }).join("");
  }

  // 2. 初期データ表示（空状態）
  renderRows([]);

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const userId = container.querySelector("#filter-user").value;
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const company = container.querySelector("#filter-company").value.toLowerCase();
    const activityStatus = container.querySelector("#filter-activity-status").value;
    const contractStatus = container.querySelector("#filter-contract-status").value;

    // チェックボックスで選択された指標
    const selectedMetrics = [];
    container.querySelectorAll("input[type='checkbox']:checked").forEach(cb => {
      selectedMetrics.push(cb.value);
    });

    // API から営業活動データを取得
    const activities = await window.aivicApi.list(activityTableIndex);
    if (!activities) return;

    // フィルタリング
    let filtered = activities.filter(a => {
      // ユーザーフィルタ
      if (userId && a.ユーザーID !== userId && a.ユーザー名 !== userId) return false;

      // 期間フィルタ
      if (dateFrom) {
        const actDate = new Date(a.活動日);
        if (actDate < new Date(dateFrom)) return false;
      }
      if (dateTo) {
        const actDate = new Date(a.活動日);
        if (actDate > new Date(dateTo)) return false;
      }

      // 顧客企業名フィルタ
      if (company && !a.顧客名.toLowerCase().includes(company)) return false;

      // 営業活動ステータスフィルタ
      if (activityStatus && a.活動種別 !== activityStatus) return false;

      // 成約ステータスフィルタ
      if (contractStatus === '成約' && !a.成果有無) return false;
      if (contractStatus === '未成約' && a.成果有無) return false;

      return true;
    });

    renderRows(filtered);
  });

  // 4. リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-user").value = "";
    container.querySelector("#filter-date-from").value = "";
    container.querySelector("#filter-date-to").value = "";
    container.querySelector("#filter-company").value = "";
    container.querySelector("#filter-activity-status").value = "";
    container.querySelector("#filter-contract-status").value = "";
    container.querySelectorAll("input[type='checkbox']").forEach(cb => cb.checked = false);
    renderRows([]);
  });

  // 5. CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const activities = await window.aivicApi.list(activityTableIndex);
    if (!activities || activities.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    // ヘッダー行
    const headers = ["活動日", "営業担当者", "顧客企業", "活動種別", "案件名", "成果金額", "成約状況"];

    // データ行
    const rows = activities.map(a => [
      new Date(a.活動日).toLocaleDateString('ja-JP'),
      a.ユーザー名 || a.営業担当者 || "",
      a.顧客名 || "",
      a.活動種別 || "",
      a.案件名 || "",
      a.成果金額 || "",
      a.成果有無 ? "成約" : "未成約"
    ]);

    // CSV 変換（BOM 付き）
    const csv = "\uFEFF" + [headers, ...rows].map(row => 
      row.map(cell => {
        const str = String(cell || "");
        return str.includes(",") || str.includes('"') || str.includes("\n") 
          ? `"${str.replace(/"/g, '""')}"` 
          : str;
      }).join(",")
    ).join("\n");

    // ダウンロード
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `営業データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 6. 詳細ボタンのイベントデリゲーション
  container.addEventListener("click", async e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細画面へ遷移（実装例）
      alert(`営業活動ID: ${id} の詳細を表示します`);
      // 実装時は window.showScreen("detail-screen-id") など
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const TABLE_USERS = 0;
  const TABLE_CUSTOMERS = 1;
  const TABLE_METRICS = 2;
  const TABLE_TEMPLATES = 3;
  const TABLE_REPORTS = 4;

  // 1. 最近生成されたレポート再描画関数
  function renderRecentReports(rows) {
    const tbody = container.querySelector("#recent-reports-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="3" style="padding: 8px; text-align: center; color: var(--text-muted);">レポートはまだ生成されていません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.slice(0, 5).map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 6px 0; color: var(--text);">${r.レポートタイトル || r.reportTitle || '無題'}</td>
        <td style="padding: 6px 0; color: var(--text-muted);">${r.生成日時 ? new Date(r.生成日時).toLocaleString('ja-JP') : '-'}</td>
        <td style="padding: 6px 0; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 12px; background: ${r.配信ステータス === '配信済み' ? 'rgba(76,175,80,0.2)' : 'rgba(255,152,0,0.2)'}; color: ${r.配信ステータス === '配信済み' ? '#4caf50' : '#ff9800'};">
            ${r.配信ステータス || '未配信'}
          </span>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(TABLE_REPORTS).then(rows => {
    renderRecentReports(rows);
  });

  // 3. 自動配信トグル
  const autoDeliveryToggle = container.querySelector("#auto-delivery-toggle");
  const deliverySettings = container.querySelector("#delivery-settings");
  autoDeliveryToggle.addEventListener("change", () => {
    deliverySettings.style.display = autoDeliveryToggle.checked ? "block" : "none";
  });

  // 4. プレビューボタン
  container.querySelector("#preview-button").addEventListener("click", async () => {
    const templateId = container.querySelector("#template-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const selectedUsers = Array.from(container.querySelectorAll("input[name='user']:checked")).map(el => el.value);
    const selectedMetrics = Array.from(container.querySelectorAll("input[name='metric']:checked")).map(el => el.value);
    const reportName = container.querySelector("#report-name").value;

    if (!templateId || !periodStart || !periodEnd || selectedUsers.length === 0 || selectedMetrics.length === 0) {
      alert("テンプレート、期間、対象ユーザー、成果指標を選択してください");
      return;
    }

    // プレビュー内容を生成
    const previewPanel = container.querySelector("#preview-panel");
    previewPanel.innerHTML = `
      <div style="color: var(--text);">
        <p style="margin: 0 0 8px 0; font-weight: 600;">レポート名: ${reportName || '(未設定)'}</p>
        <p style="margin: 0 0 8px 0; font-size: 12px; color: var(--text-muted);">期間: ${periodStart} ～ ${periodEnd}</p>
        <p style="margin: 0 0 8px 0; font-size: 12px; color: var(--text-muted);">対象ユーザー: ${selectedUsers.length}名</p>
        <p style="margin: 0 0 8px 0; font-size: 12px; color: var(--text-muted);">成果指標: ${selectedMetrics.join(', ')}</p>
        <hr style="border: none; border-top: 1px solid rgba(255,255,255,0.12); margin: 12px 0;" />
        <p style="margin: 0; font-size: 12px; color: var(--text-muted);">
          このレポートは以下の内容を含みます:
          <br />• 営業活動サマリー
          <br />• 成約実績
          <br />• 指標別分析
          <br />• 営業担当者別成績
        </p>
      </div>
    `;
  });

  // 5. 生成・配信ボタン
  container.querySelector("#generate-button").addEventListener("click", async () => {
    const templateId = container.querySelector("#template-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const selectedUsers = Array.from(container.querySelectorAll("input[name='user']:checked")).map(el => el.value);
    const selectedMetrics = Array.from(container.querySelectorAll("input[name='metric']:checked")).map(el => el.value);
    const reportName = container.querySelector("#report-name").value;
    const autoDelivery = container.querySelector("#auto-delivery-toggle").checked;
    const deliveryEmail = container.querySelector("#delivery-email").value;
    const deliverySchedule = container.querySelector("#delivery-schedule").value;
    const deliveryFrequency = container.querySelector("input[name='delivery-frequency']:checked")?.value;

    if (!templateId || !periodStart || !periodEnd || selectedUsers.length === 0 || selectedMetrics.length === 0 || !reportName) {
      alert("必須項目をすべて入力してください");
      return;
    }

    if (autoDelivery && (!deliveryEmail || !deliverySchedule || !deliveryFrequency)) {
      alert("自動配信を有効にする場合、配信先メール、スケジュール、頻度を設定してください");
      return;
    }

    // レポート生成データ
    const reportData = {
      テンプレートID: templateId,
      レポート期間開始日: periodStart,
      レポート期間終了日: periodEnd,
      レポートタイトル: reportName,
      配信ステータス: autoDelivery ? '配信予定' : '未配信',
      配信先メールアドレス: deliveryEmail || null,
      成約件数: Math.floor(Math.random() * 20) + 5,
      営業活動件数: Math.floor(Math.random() * 100) + 30
    };

    const saved = await window.aivicApi.save(TABLE_REPORTS, reportData);
    if (saved) {
      alert("レポートが生成されました");
      // 最近生成されたレポート一覧を更新
      window.aivicApi.list(TABLE_REPORTS).then(renderRecentReports);
      // フォームをリセット
      container.querySelector("#report-name").value = "";
    }
  });

  // 6. テンプレート管理ボタン
  container.querySelector("#template-manage-button").addEventListener("click", () => {
    window.showScreen("scr-1781954055121");
  });

  // 7. 配信履歴ボタン
  container.querySelector("#delivery-history-button").addEventListener("click", () => {
    window.showScreen("scr-1781954135704");
  });

  // 8. 成果指標ダッシュボードボタン
  container.querySelector("#metric-dashboard-button").addEventListener("click", () => {
    window.showScreen("scr-1781954119708");
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const REPORT_TABLE_IDX = 0;      // 生成済みレポート
  const DELIVERY_HISTORY_IDX = 1;  // レポート配信履歴
  const USER_TABLE_IDX = 2;        // ユーザー（配信先）

  let allReports = [];
  let selectedReportId = null;
  let selectedTargets = new Set();

  // ===== 1. レポート一覧の再描画 =====
  function renderReportList(reports) {
    const tbody = container.querySelector("#report-tbody");
    if (!reports || reports.length === 0) {
      tbody.innerHTML = '<tr><td colspan="2" style="padding: 20px; text-align: center; color: var(--text-muted);">レポートがありません</td></tr>';
      return;
    }

    tbody.innerHTML = reports.map(r => {
      const statusColor = r.配信ステータス === '配信済み' ? '#4ade80' : 
                          r.配信ステータス === '配信失敗' ? '#ef4444' : '#f59e0b';
      const statusLabel = r.配信ステータス || '未配信';
      return `
        <tr data-id="${r.id}" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.05); transition: background 0.2s;" 
            onmouseover="this.style.background='rgba(255,255,255,0.05)'" 
            onmouseout="this.style.background='transparent'">
          <td style="padding: 8px; color: var(--text);">
            <div style="font-weight: 500; font-size: 13px;">${r.レポートタイトル || 'レポート'}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${new Date(r.生成日時).toLocaleDateString('ja-JP')}</div>
          </td>
          <td style="padding: 8px; text-align: center;">
            <span style="display: inline-block; background: ${statusColor}; color: #fff; padding: 3px 6px; border-radius: 3px; font-size: 11px; font-weight: 600;">${statusLabel}</span>
          </td>
        </tr>
      `;
    }).join('');

    // 行クリックでレポート詳細を表示
    tbody.querySelectorAll('tr[data-id]').forEach(tr => {
      tr.addEventListener('click', () => {
        selectedReportId = tr.dataset.id;
        const report = reports.find(r => r.id === selectedReportId);
        if (report) {
          renderReportDetail(report);
          renderDistributionTargets(report);
          renderDeliveryTimeline(report);
        }
      });
    });
  }

  // ===== 2. レポート詳細の表示 =====
  function renderReportDetail(report) {
    const detail = container.querySelector("#report-detail");
    const period = `${new Date(report.レポート期間開始日).toLocaleDateString('ja-JP')} ～ ${new Date(report.レポート期間終了日).toLocaleDateString('ja-JP')}`;

    detail.innerHTML = `
      <div style="margin-bottom: 12px;">
        <h2 style="margin: 0 0 4px 0; font-size: 18px; font-weight: 700; color: var(--text);">${report.レポートタイトル || 'レポート'}</h2>
        <p style="margin: 0; font-size: 12px; color: var(--text-muted);">生成日時: ${new Date(report.生成日時).toLocaleString('ja-JP')}</p>
      </div>

      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 12px;">
        <div style="background: rgba(212, 165, 116, 0.1); padding: 10px; border-radius: 4px; border-left: 3px solid #d4a574;">
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">対象期間</div>
          <div style="font-size: 14px; font-weight: 600; color: var(--text);">${period}</div>
        </div>
        <div style="background: rgba(196, 30, 58, 0.1); padding: 10px; border-radius: 4px; border-left: 3px solid #c41e3a;">
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">配信状態</div>
          <div style="font-size: 14px; font-weight: 600; color: var(--text);">${report.配信ステータス || '未配信'}</div>
        </div>
      </div>

      <div style="background: rgba(0,0,0,0.2); padding: 10px; border-radius: 4px; margin-bottom: 12px;">
        <h4 style="margin: 0 0 8px 0; font-size: 13px; font-weight: 600; color: var(--text);">営業成果サマリー</h4>
        <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px;">
          <div style="background: var(--bg-main); padding: 8px; border-radius: 3px; text-align: center;">
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">成約件数</div>
            <div style="font-size: 20px; font-weight: 700; color: #4ade80;">${report.成約件数 || 0}</div>
          </div>
          <div style="background: var(--bg-main); padding: 8px; border-radius: 3px; text-align: center;">
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">営業活動件数</div>
            <div style="font-size: 20px; font-weight: 700; color: #60a5fa;">${report.営業活動件数 || 0}</div>
          </div>
          <div style="background: var(--bg-main); padding: 8px; border-radius: 3px; text-align: center;">
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">成約率</div>
            <div style="font-size: 20px; font-weight: 700; color: #fbbf24;">${report.営業活動件数 > 0 ? Math.round((report.成約件数 / report.営業活動件数) * 100) : 0}%</div>
          </div>
        </div>
      </div>

      <div style="background: rgba(0,0,0,0.2); padding: 10px; border-radius: 4px;">
        <h4 style="margin: 0 0 6px 0; font-size: 13px; font-weight: 600; color: var(--text);">レポート内容</h4>
        <div style="font-size: 12px; color: var(--text); line-height: 1.6; max-height: 200px; overflow-y: auto; white-space: pre-wrap; word-break: break-word;">
          ${(report.レポート内容 || 'レポート内容なし').substring(0, 500)}
        </div>
      </div>
    `;
  }

  // ===== 3. 配信先選択パネルの表示 =====
  function renderDistributionTargets(report) {
    const targetsDiv = container.querySelector("#distribution-targets");
    selectedTargets.clear();

    if (!report.配信先メールアドレス) {
      targetsDiv.innerHTML = '<p style="margin: 0; color: var(--text-muted); font-size: 12px;">配信先が設定されていません</p>';
      return;
    }

    const emails = report.配信先メールアドレス.split(',').map(e => e.trim()).filter(e => e);
    targetsDiv.innerHTML = emails.map((email, idx) => `
      <label style="display: flex; align-items: center; padding: 6px; cursor: pointer; border-radius: 3px; transition: background 0.2s;" 
             onmouseover="this.style.background='rgba(255,255,255,0.05)'" 
             onmouseout="this.style.background='transparent'">
        <input type="checkbox" value="${email}" data-testid="target-${idx}" style="margin-right: 6px; cursor: pointer; accent-color: var(--primary);" />
        <span style="font-size: 12px; color: var(--text);">${email}</span>
      </label>
    `).join('');

    // チェックボックス変更時に selectedTargets を更新
    targetsDiv.querySelectorAll('input[type="checkbox"]').forEach(cb => {
      cb.addEventListener('change', () => {
        if (cb.checked) {
          selectedTargets.add(cb.value);
        } else {
          selectedTargets.delete(cb.value);
        }
      });
    });
  }

  // ===== 4. 配信履歴タイムラインの表示 =====
  function renderDeliveryTimeline(report) {
    const timeline = container.querySelector("#delivery-timeline");

    window.aivicApi.list(DELIVERY_HISTORY_IDX).then(histories => {
      const reportHistories = (histories || []).filter(h => h.生成済みレポートID === report.id);

      if (reportHistories.length === 0) {
        timeline.innerHTML = '<p style="margin: 0; color: var(--text-muted); font-size: 12px;">配信履歴がありません</p>';
        return;
      }

      timeline.innerHTML = reportHistories.map(h => {
        const statusColor = h.配信ステータス === '成功' ? '#4ade80' : 
                           h.配信ステータス === '失敗' ? '#ef4444' : '#f59e0b';
        return `
          <div style="margin-bottom: 8px; padding: 8px; background: rgba(0,0,0,0.2); border-left: 3px solid ${statusColor}; border-radius: 3px;">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 3px;">
              <span style="font-weight: 600; color: var(--text); font-size: 12px;">${h.配信先メールアドレス}</span>
              <span style="background: ${statusColor}; color: #fff; padding: 2px 6px; border-radius: 2px; font-size: 10px; font-weight: 600;">${h.配信ステータス}</span>
            </div>
            <div style="font-size: 11px; color: var(--text-muted);">${new Date(h.配信日時).toLocaleString('ja-JP')}</div>
            ${h.開封フラグ ? `<div style="font-size: 11px; color: #4ade80; margin-top: 2px;">✓ 開封済み (${new Date(h.開封日時).toLocaleString('ja-JP')})</div>` : ''}
          </div>
        `;
      }).join('');
    });
  }

  // ===== 5. 初期データ読み込み =====
  window.aivicApi.list(REPORT_TABLE_IDX).then(reports => {
    allReports = reports || [];
    renderReportList(allReports);
  });

  // ===== 6. フィルタ検索 =====
  container.querySelector("#btn-filter").addEventListener("click", () => {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const status = container.querySelector("#filter-status").value;

    let filtered = allReports;

    if (startDate) {
      filtered = filtered.filter(r => new Date(r.生成日時) >= new Date(startDate));
    }
    if (endDate) {
      filtered = filtered.filter(r => new Date(r.生成日時) <= new Date(endDate + 'T23:59:59'));
    }
    if (status) {
      filtered = filtered.filter(r => r.配信ステータス === status);
    }

    renderReportList(filtered);
  });

  // ===== 7. 配信実行ボタン =====
  container.querySelector("#btn-send").addEventListener("click", () => {
    if (!selectedReportId) {
      alert("レポートを選択してください");
      return;
    }
    if (selectedTargets.size === 0) {
      alert("配信先を選択してください");
      return;
    }

    const report = allReports.find(r => r.id === selectedReportId);
    const modal = container.querySelector("#modal-confirm-send");
    const confirmText = container.querySelector("#modal-confirm-text");
    confirmText.textContent = `${Array.from(selectedTargets).join(', ')} に配信します。よろしいですか？`;
    modal.style.display = "flex";

    container.querySelector("#btn-modal-confirm").onclick = async () => {
      modal.style.display = "none";

      // 配信履歴レコードを作成
      for (const email of selectedTargets) {
        await window.aivicApi.save(DELIVERY_HISTORY_IDX, {
          生成済みレポートID: selectedReportId,
          配信先メールアドレス: email,
          配信日時: new Date().toISOString(),
          配信ステータス: '成功',
          配信方法: 'メール',
          開封フラグ: false,
          再配信フラグ: false,
          再配信回数: 0
        });
      }

      // レポートの配信ステータスを更新
      await window.aivicApi.update(REPORT_TABLE_IDX, selectedReportId, {
        配信ステータス: '配信済み',
        配信日時: new Date().toISOString()
      });

      alert("配信しました");
      window.aivicApi.list(REPORT_TABLE_IDX).then(reports => {
        allReports = reports || [];
        renderReportList(allReports);
        if (selectedReportId) {
          const report = allReports.find(r => r.id === selectedReportId);
          if (report) {
            renderReportDetail(report);
            renderDeliveryTimeline(report);
          }
        }
      });
    };
  });

  // ===== 8. 再配信ボタン =====
  container.querySelector("#btn-resend").addEventListener("click", () => {
    if (!selectedReportId) {
      alert("レポートを選択してください");
      return;
    }

    window.aivicApi.list(DELIVERY_HISTORY_IDX).then(histories => {
      const failedHistories = (histories || []).filter(h => 
        h.生成済みレポートID === selectedReportId && h.配信ステータス === '失敗'
      );

      if (failedHistories.length === 0) {
        alert("再配信対象がありません");
        return;
      }

      if (confirm(`${failedHistories.length}件の失敗配信を再配信しますか？`)) {
        failedHistories.forEach(h => {
          window.aivicApi.update(DELIVERY_HISTORY_IDX, h.id, {
            配信ステータス: '成功',
            配信日時: new Date().toISOString(),
            再配信フラグ: true,
            再配信回数: (h.再配信回数 || 0) + 1
          });
        });
        alert("再配信しました");
        renderDeliveryTimeline(allReports.find(r => r.id === selectedReportId));
      }
    });
  });

  // ===== 9. モーダルキャンセルボタン =====
  container.querySelector("#btn-modal-cancel").addEventListener("click", () => {
    container.querySelector("#modal-confirm-send").style.display = "none";
  });
}

function(container, apiUrl, tables) {
  // ===== 1. グラフ描画関数 =====
  function drawRevenueChart() {
    const canvas = container.querySelector('#chart-revenue-trend');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    const months = ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月'];
    const data = [3200, 3500, 3800, 4100, 4200, 4500, 4600, 4800, 4900, 5000, 4800, 4375];
    const maxVal = 5500;
    const padding = 30;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const barWidth = chartWidth / months.length * 0.7;
    const barGap = chartWidth / months.length;

    // 背景
    ctx.fillStyle = 'rgba(0,0,0,0.1)';
    ctx.fillRect(padding, padding, chartWidth, chartHeight);

    // グリッドライン
    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = padding + (chartHeight / 5) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(padding + chartWidth, y);
      ctx.stroke();
    }

    // 棒グラフ
    data.forEach((val, idx) => {
      const barHeight = (val / maxVal) * chartHeight;
      const x = padding + idx * barGap + (barGap - barWidth) / 2;
      const y = padding + chartHeight - barHeight;
      ctx.fillStyle = '#d4af37';
      ctx.fillRect(x, y, barWidth, barHeight);
    });

    // X軸ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'center';
    months.forEach((month, idx) => {
      const x = padding + idx * barGap + barGap / 2;
      ctx.fillText(month, x, canvas.height - 8);
    });

    // Y軸ラベル
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const val = Math.round((maxVal / 5) * i / 100) * 100;
      const y = padding + chartHeight - (chartHeight / 5) * i;
      ctx.fillText('¥' + (val / 100).toFixed(0) + '万', padding - 8, y + 4);
    }
  }

  function drawActivityTypeChart() {
    const canvas = container.querySelector('#chart-activity-type');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    const types = ['訪問', '電話', 'メール'];
    const values = [78, 52, 26];
    const colors = ['#d4af37', '#cc8844', '#aa6644'];
    const total = values.reduce((a, b) => a + b, 0);

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(canvas.width, canvas.height) / 2 - 20;

    let startAngle = -Math.PI / 2;
    values.forEach((val, idx) => {
      const sliceAngle = (val / total) * 2 * Math.PI;
      ctx.fillStyle = colors[idx];
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, startAngle, startAngle + sliceAngle);
      ctx.closePath();
      ctx.fill();

      // ラベル
      const labelAngle = startAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius * 0.6);
      const labelY = centerY + Math.sin(labelAngle) * (radius * 0.6);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 12px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(types[idx], labelX, labelY);

      startAngle += sliceAngle;
    });
  }

  function drawConversionRateChart() {
    const canvas = container.querySelector('#chart-conversion-rate');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    const months = ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月'];
    const rates = [18, 19, 21, 22, 23, 24, 25, 26, 27, 28, 27, 26.9];
    const padding = 30;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const pointGap = chartWidth / (months.length - 1);

    // 背景
    ctx.fillStyle = 'rgba(0,0,0,0.1)';
    ctx.fillRect(padding, padding, chartWidth, chartHeight);

    // グリッドライン
    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = padding + (chartHeight / 5) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(padding + chartWidth, y);
      ctx.stroke();
    }

    // 折れ線グラフ
    ctx.strokeStyle = '#d4af37';
    ctx.lineWidth = 2;
    ctx.beginPath();
    rates.forEach((rate, idx) => {
      const x = padding + idx * pointGap;
      const y = padding + chartHeight - (rate / 30) * chartHeight;
      if (idx === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // ポイント
    ctx.fillStyle = '#d4af37';
    rates.forEach((rate, idx) => {
      const x = padding + idx * pointGap;
      const y = padding + chartHeight - (rate / 30) * chartHeight;
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, 2 * Math.PI);
      ctx.fill();
    });

    // X軸ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'center';
    months.forEach((month, idx) => {
      const x = padding + idx * pointGap;
      ctx.fillText(month, x, canvas.height - 8);
    });

    // Y軸ラベル
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const val = (30 / 5) * i;
      const y = padding + chartHeight - (chartHeight / 5) * i;
      ctx.fillStyle = '#9fb0d1';
      ctx.fillText(val.toFixed(0) + '%', padding - 8, y + 4);
    }
  }

  // ===== 2. イベントリスナー登録 =====

  // フィルター適用ボタン
  container.querySelector('[data-testid="apply-filter-button"]').addEventListener('click', () => {
    const period = container.querySelector('[data-testid="period-filter"]').value;
    const salesperson = container.querySelector('[data-testid="salesperson-filter"]').value;
    const category = container.querySelector('[data-testid="category-filter"]').value;
    console.log('フィルター適用:', { period, salesperson, category });
    // 実際のフィルタリング処理はここに実装
    drawRevenueChart();
    drawActivityTypeChart();
    drawConversionRateChart();
  });

  // CSVエクスポートボタン
  container.querySelector('[data-testid="export-csv-button"]').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ['順位', '担当者', '売上', '成約件数'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...rows.slice(0, 5).map((r, i) => [i + 1, r.name || '', r.revenue || '', r.contracts || ''].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'dashboard_export.csv';
    link.click();
  });

  // テンプレート管理ボタン
  container.querySelector('[data-testid="template-management-button"]').addEventListener('click', () => {
    window.showScreen('scr-1781954055121');
  });

  // レポート自動生成ボタン
  container.querySelector('[data-testid="auto-generate-button"]').addEventListener('click', () => {
    window.showScreen('scr-1781954086842');
  });

  // ===== 3. 初期描画 =====
  setTimeout(() => {
    drawRevenueChart();
    drawActivityTypeChart();
    drawConversionRateChart();
  }, 100);
}

function(container, apiUrl, tables) {
  const tableIndex = 0; // レポート配信履歴テーブル
