              ${r.配信ステータス || "−"}
            </span>
          </td>
          <td style="padding: 0.75rem; text-align: center; color: var(--text);">${openedFlag}</td>
          <td style="padding: 0.75rem; text-align: center; color: var(--text);">${resendCount}</td>
          <td style="padding: 0.75rem; text-align: center; display: flex; gap: 0.25rem; justify-content: center;">
            <button class="detail-btn" data-id="${r.配信履歴ID}" style="background: transparent; color: var(--primary); border: 1px solid var(--primary); padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.7rem; cursor: pointer;">詳細</button>
            <button class="resend-btn" data-id="${r.配信履歴ID}" style="background: transparent; color: var(--primary); border: 1px solid var(--primary); padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.7rem; cursor: pointer;">再配信</button>
          </td>
        </tr>
      `;
    }).join("");

    container.querySelector("#record-count").textContent = `全 ${rows.length} 件`;
  }

  // 2. 初期データ読み込み
  async function loadInitialData() {
    const rows = await window.aivicApi.list(tableIndex);
    if (rows) {
      allRows = rows;
      renderRows(allRows);
    }
  }
  loadInitialData();

  // 3. 検索ボタン
  container.querySelector("#search-button").addEventListener("click", async () => {
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const status = container.querySelector("#filter-status").value;

    let filtered = allRows;
    if (dateFrom) {
      const fromTime = new Date(dateFrom).getTime();
      filtered = filtered.filter(r => new Date(r.配信日時).getTime() >= fromTime);
    }
    if (dateTo) {
      const toTime = new Date(dateTo).getTime() + 86400000; // 終了日の翌日まで
      filtered = filtered.filter(r => new Date(r.配信日時).getTime() < toTime);
    }
    if (status) {
      filtered = filtered.filter(r => r.配信ステータス === status);
    }

    currentPage = 0;
    renderRows(filtered);
  });

  // 4. リセットボタン
  container.querySelector("#reset-button").addEventListener("click", () => {
    container.querySelector("#filter-date-from").value = "";
    container.querySelector("#filter-date-to").value = "";
    container.querySelector("#filter-status").value = "";
    currentPage = 0;
    renderRows(allRows);
