            </div>
            <div>
              <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">レポート名</label>
              <p style="color: var(--text); margin: 0.25rem 0 0 0;">${row.レポート名 || "−"}</p>
            </div>
            <div>
              <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">配信日時</label>
              <p style="color: var(--text); margin: 0.25rem 0 0 0;">${row.配信日時 ? new Date(row.配信日時).toLocaleString("ja-JP") : "−"}</p>
            </div>
            <div>
              <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">配信ステータス</label>
              <p style="color: var(--text); margin: 0.25rem 0 0 0;">${row.配信ステータス || "−"}</p>
            </div>
            <div>
              <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">配信先メール</label>
              <p style="color: var(--text); margin: 0.25rem 0 0 0;">${row.配信先メールアドレス || "−"}</p>
            </div>
            <div>
              <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">開封フラグ</label>
              <p style="color: var(--text); margin: 0.25rem 0 0 0;">${row.開封フラグ ? "開封済み" : "未開封"}</p>
            </div>
            <div>
              <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">開封日時</label>
              <p style="color: var(--text); margin: 0.25rem 0 0 0;">${row.開封日時 ? new Date(row.開封日時).toLocaleString("ja-JP") : "−"}</p>
            </div>
            <div>
              <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">再配信回数</label>
              <p style="color: var(--text); margin: 0.25rem 0 0 0;">${row.再配信回数 || 0}</p>
            </div>
          </div>
          ${row.エラーメッセージ ? `
            <div style="background: rgba(239,68,68,0.1); border-left: 3px solid #ef4444; padding: 0.75rem; border-radius: 0.375rem; margin-top: 1rem;">
              <label style="font-size: 0.75rem; color: #ef4444; font-weight: 600;">エラーメッセージ</label>
              <p style="color: var(--text); margin: 0.25rem 0 0 0; font-size: 0.8rem;">${row.エラーメッセージ}</p>
            </div>
          ` : ""}
        `;
        container.querySelector("#detail-modal").removeAttribute("hidden");
      }
    }
  });

  // 7. モーダル閉じるボタン
  container.querySelector("#close-detail-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").setAttribute("hidden", "");
  });
  container.querySelector("#close-modal-btn").addEventListener("click", () => {
    container.querySelector("#detail-modal").setAttribute("hidden", "");
  });

  // 8. 再配信ボタン（テーブル行から）
  container.addEventListener("click", async e => {
    const resendBtn = e.target.closest(".resend-btn");
    if (resendBtn) {
      const rowId = resendBtn.dataset.id;
      if (confirm("このレポートを再配信しますか？")) {
        const updated = await window.aivicApi.update(tableIndex, rowId, {
          再配信フラグ: true,
          再配信回数: (allRows.find(r => r.配信履歴ID === rowId)?.再配信回数 || 0) + 1,
          更新日時: new Date().toISOString()
        });
        if (updated) {
          alert("再配信をリクエストしました");
          const rows = await window.aivicApi.list(tableIndex);
          if (rows) {
            allRows = rows;
            renderRows(allRows);
          }
        }
      }
    }
  });

  // 9. モーダルからの再配信
  container.querySelector("#resend-from-modal").addEventListener("click", async () => {
    if (!selectedRowId) return;
    if (confirm("このレポートを再配信しますか？")) {
      const updated = await window.aivicApi.update(tableIndex, selectedRowId, {
        再配信フラグ: true,
        再配信回数: (allRows.find(r => r.配信履歴ID === selectedRowId)?.再配信回数 || 0) + 1,
        更新日時: new Date().toISOString()
      });
      if (updated) {
