    const tbody = container.querySelector("#report-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);"><td colspan="4" style="padding: 8px; text-align: center; color: var(--text-muted);">生成済みレポートはありません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 6px; color: var(--text);">${(r.レポートID || r.id || '').substring(0, 8)}</td>
        <td style="padding: 6px; color: var(--text);">${r.生成日時 ? new Date(r.生成日時).toLocaleString('ja-JP') : '-'}</td>
        <td style="padding: 6px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 2px; font-size: 11px; background: ${r.配信ステータス === '配信済み' ? 'rgba(76,175,80,0.2)' : r.配信ステータス === '配信失敗' ? 'rgba(244,67,54,0.2)' : 'rgba(255,193,7,0.2)'}; color: ${r.配信ステータス === '配信済み' ? '#4caf50' : r.配信ステータス === '配信失敗' ? '#f44336' : '#ffc107'};">${r.配信ステータス || '未配信'}</span>
        </td>
        <td style="padding: 6px; text-align: center;">
          <button class="action-btn secondary view-btn" data-id="${r.id}" style="padding: 3px 8px; font-size: 11px; border: 1px solid rgba(255,255,255,0.18); background: transparent; color: var(--text); cursor: pointer; border-radius: 2px;">詳細</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. KPI 集計の更新
  function updateKPI() {
    const monthInput = container.querySelector("#report-month").value;
    if (!monthInput) {
      container.querySelector("#kpi-contracts").textContent = "-";
      container.querySelector("#kpi-revenue").textContent = "-";
      container.querySelector("#kpi-activities").textContent = "-";
      container.querySelector("#kpi-rate").textContent = "-";
      return;
    }

    const [year, month] = monthInput.split('-');
    const startDate = new Date(year, parseInt(month) - 1, 1);
    const endDate = new Date(year, parseInt(month), 0);

    const contracts = (tables[contractTableIdx]?.records || []).filter(c => {
      const d = new Date(c.成約日);
      return d >= startDate && d <= endDate;
    });
    const activities = (tables[activityTableIdx]?.records || []).filter(a => {
      const d = new Date(a.活動日);
      return d >= startDate && d <= endDate;
    });

    const totalRevenue = contracts.reduce((sum, c) => sum + (c.成約金額 || 0), 0);
    const rate = activities.length > 0 ? ((contracts.length / activities.length) * 100).toFixed(1) : 0;

    container.querySelector("#kpi-contracts").textContent = contracts.length;
    container.querySelector("#kpi-revenue").textContent = (totalRevenue / 1000000).toFixed(1) + "M";
    container.querySelector("#kpi-activities").textContent = activities.length;
    container.querySelector("#kpi-rate").textContent = rate + "%";
  }

  // 3. プレビュー更新
  function updatePreview() {
    const templateId = container.querySelector("#template-select").value;
    const monthInput = container.querySelector("#report-month").value;
    const previewContent = container.querySelector("#preview-content");

    if (!templateId || !monthInput) {
      previewContent.innerHTML = '<p style="color: var(--text-muted); text-align: center; margin: 20px 0;">テンプレートと対象月を選択してください</p>';
      return;
    }

    const [year, month] = monthInput.split('-');
    const template = (tables[templateTableIdx]?.records || []).find(t => t.id === templateId);
    const monthStr = `${year}年${month}月`;

    let html = `<strong style="color: var(--primary); font-size: 13px;">営業成果レポート - ${monthStr}</strong><br/>`;
    html += `<br/><strong>テンプレート:</strong> ${template?.テンプレート名 || 'N/A'}<br/>`;
    html += `<strong>生成日時:</strong> ${new Date().toLocaleString('ja-JP')}<br/>`;
    html += `<br/>【成果指標】<br/>`;
    html += `・成約件数: ${container.querySelector("#kpi-contracts").textContent}<br/>`;
    html += `・成約金額: ${container.querySelector("#kpi-revenue").textContent}<br/>`;
    html += `・営業活動件数: ${container.querySelector("#kpi-activities").textContent}<br/>`;
    html += `・成約率: ${container.querySelector("#kpi-rate").textContent}<br/>`;
    html += `<br/>【配信先】<br/>`;
    const emails = container.querySelector("#delivery-emails").value.split(',').filter(e => e.trim());
    html += emails.length > 0 ? emails.map(e => `・${e.trim()}`).join('<br/>') : '・未設定';

    previewContent.innerHTML = html;
  }

  // 4. 初期データ読み込み
  window.aivicApi.list(reportTableIdx).then(rows => {
    renderReportList(rows || []);
  });

  // 5. イベントリスナー登録
  container.querySelector("#report-month").addEventListener("change", () => {
    updateKPI();
    updatePreview();
  });

  container.querySelector("#template-select").addEventListener("change", updatePreview);
  container.querySelector("#delivery-emails").addEventListener("input", updatePreview);

  container.querySelector("#btn-preview").addEventListener("click", updatePreview);

  // 6. 生成・配信実行ボタン
  container.querySelector("#btn-generate").addEventListener("click", async () => {
    const month = container.querySelector("#report-month").value;
    const userId = container.querySelector("#target-user").value;
    const templateId = container.querySelector("#template-select").value;
    const emails = container.querySelector("#delivery-emails").value;
    const schedule = container.querySelector("#delivery-schedule").value;

    if (!month || !userId || !templateId || !emails) {
      alert("必須項目を入力してください");
      return;
    }

    const [year, monthNum] = month.split('-');
    const startDate = new Date(year, parseInt(monthNum) - 1, 1);
    const endDate = new Date(year, parseInt(monthNum), 0);

    const newReport = {
      テンプレートID: templateId,
      ユーザーID: userId,
      レポート期間開始日: startDate.toISOString(),
      レポート期間終了日: endDate.toISOString(),
      生成日時: new Date().toISOString(),
      レポートタイトル: `営業成果レポート ${year}年${monthNum}月`,
      レポート内容: container.querySelector("#preview-content").innerHTML,
      配信ステータス: "配信済み",
      配信日時: new Date().toISOString(),
      配信先メールアドレス: emails,
      成約件数: parseInt(container.querySelector("#kpi-contracts").textContent) || 0,
      営業活動件数: parseInt(container.querySelector("#kpi-activities").textContent) || 0,
    };

    const saved = await window.aivicApi.save(reportTableIdx, newReport);
    if (saved) {
      alert("レポートを生成・配信しました");
      window.aivicApi.list(reportTableIdx).then(renderReportList);
    }
  });

  // 7. 詳細表示ボタン
  container.addEventListener("click", async e => {
    const viewBtn = e.target.closest(".view-btn");
    if (viewBtn) {
      const reportId = viewBtn.dataset.id;
      // 詳細画面へ遷移（生成済みレポート確認・配信画面）
      window.showScreen("scr-1781954103241");
    }
  });

  // 初期 KPI 更新
  updateKPI();
}

