function(container, apiUrl, tables) {
  // ========== 1. 初期化・グローバル状態 ==========
  let activityData = [];
  let contractData = [];
  let aggregatedData = [];
  const selectedMetrics = new Set(['revenue', 'contract', 'activity', 'unit_price', 'rate']);

  // ========== 2. 集計結果を描画する関数 ==========
  function renderAggregateResults() {
    const tbody = container.querySelector('#aggregate-tbody');
    if (aggregatedData.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.04);"><td colspan="5" style="padding: 12px 8px; text-align: center; color: var(--text-muted); font-size: 11px;">集計データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = aggregatedData.map(row => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.04);">
        <td style="padding: 6px 8px; text-align: left;">${row.userName || '不明'}</td>
        <td style="padding: 6px 8px; text-align: right;">¥${(row.revenue || 0).toLocaleString()}</td>
        <td style="padding: 6px 8px; text-align: right;">${row.contractCount || 0}件</td>
        <td style="padding: 6px 8px; text-align: right;">${row.activityCount || 0}件</td>
        <td style="padding: 6px 8px; text-align: right;">${row.contractRate || 0}%</td>
      </tr>
    `).join('');
  }

  // ========== 3. KPI カードを更新する関数 ==========
  function updateKPICards() {
    let totalRevenue = 0;
    let totalContracts = 0;
    let totalActivities = 0;
    let totalCustomers = new Set();
    let totalContractRate = 0;

    aggregatedData.forEach(row => {
      totalRevenue += row.revenue || 0;
      totalContracts += row.contractCount || 0;
      totalActivities += row.activityCount || 0;
      totalCustomers.add(row.customerId);
      totalContractRate += (row.contractRate || 0);
    });

    const avgContractRate = aggregatedData.length > 0 ? Math.round(totalContractRate / aggregatedData.length) : 0;
    const unitPrice = totalCustomers.size > 0 ? Math.round(totalRevenue / totalCustomers.size) : 0;

    if (selectedMetrics.has('revenue')) {
      container.querySelector('#kpi-revenue').textContent = '¥' + totalRevenue.toLocaleString();
    }
    if (selectedMetrics.has('contract')) {
      container.querySelector('#kpi-contract').textContent = totalContracts + '件';
    }
    if (selectedMetrics.has('activity')) {
      container.querySelector('#kpi-activity').textContent = totalActivities + '件';
    }
    if (selectedMetrics.has('unit_price')) {
      container.querySelector('#kpi-unit-price').textContent = '¥' + unitPrice.toLocaleString();
    }
    if (selectedMetrics.has('rate')) {
      container.querySelector('#kpi-rate').textContent = avgContractRate + '%';
    }
  }

  // ========== 4. 集計処理メイン関数 ==========
  function performAggregation() {
    const periodStart = container.querySelector('#period-start').value;
    const periodEnd = container.querySelector('#period-end').value;
    const filterUser = container.querySelector('#filter-user').value;
    const filterCompany = container.querySelector('#filter-company').value.toLowerCase();

    // フィルタリング
    let filteredActivity = activityData;
    let filteredContract = contractData;

    if (periodStart) {
      const startDate = new Date(periodStart);
      filteredActivity = filteredActivity.filter(a => new Date(a.活動日) >= startDate);
      filteredContract = filteredContract.filter(c => new Date(c.成約日) >= startDate);
    }
    if (periodEnd) {
      const endDate = new Date(periodEnd);
      endDate.setHours(23, 59, 59, 999);
      filteredActivity = filteredActivity.filter(a => new Date(a.活動日) <= endDate);
      filteredContract = filteredContract.filter(c => new Date(c.成約日) <= endDate);
    }
    if (filterUser) {
      filteredActivity = filteredActivity.filter(a => a.ユーザーID === filterUser);
      filteredContract = filteredContract.filter(c => c.ユーザーID === filterUser);
    }
    if (filterCompany) {
      filteredActivity = filteredActivity.filter(a => (a.顧客名 || '').toLowerCase().includes(filterCompany));
      filteredContract = filteredContract.filter(c => (c.顧客企業ID || '').toLowerCase().includes(filterCompany));
    }

    // ユーザーごとに集計
    const userMap = {};
    filteredActivity.forEach(a => {
      if (!userMap[a.ユーザーID]) {
        userMap[a.ユーザーID] = {
          userId: a.ユーザーID,
          userName: a.ユーザー名 || '不明',
          revenue: 0,
          contractCount: 0,
          activityCount: 0,
          customerId: a.顧客名,
          contractRate: 0
        };
      }
      userMap[a.ユーザーID].activityCount += 1;
      if (a.成果有無) {
        userMap[a.ユーザーID].revenue += a.成果金額 || 0;
      }
    });

    filteredContract.forEach(c => {
      if (!userMap[c.ユーザーID]) {
        userMap[c.ユーザーID] = {
          userId: c.ユーザーID,
          userName: c.ユーザー名 || '不明',
          revenue: 0,
          contractCount: 0,
          activityCount: 0,
          customerId: c.顧客企業ID,
          contractRate: 0
        };
      }
      userMap[c.ユーザーID].contractCount += 1;
      userMap[c.ユーザーID].revenue += c.成約金額 || 0;
    });

    // 成約率を計算
    Object.values(userMap).forEach(user => {
      if (user.activityCount > 0) {
        user.contractRate = Math.round((user.contractCount / user.activityCount) * 100);
      }
    });

    aggregatedData = Object.values(userMap);
    renderAggregateResults();
    updateKPICards();
  }

  // ========== 5. イベントリスナー登録 ==========

  // 営業活動読込ボタン
  container.querySelector('#btn-load-activity').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(1); // 営業活動テーブルのインデックス
    if (rows) {
      activityData = rows;
      alert('営業活動データを読み込みました: ' + rows.length + '件');
    }
  });

  // 成約データ読込ボタン
  container.querySelector('#btn-load-contract').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(3); // 成約テーブルのインデックス
    if (rows) {
      contractData = rows;
      alert('成約データを読み込みました: ' + rows.length + '件');
    }
  });

  // 指標チェックボックス
  container.querySelectorAll('.metric-check').forEach(checkbox => {
    checkbox.addEventListener('change', (e) => {
      if (e.target.checked) {
        selectedMetrics.add(e.target.value);
      } else {
        selectedMetrics.delete(e.target.value);
      }
      updateKPICards();
    });
  });

  // 集計実行ボタン
  container.querySelector('#btn-aggregate').addEventListener('click', () => {
    if (activityData.length === 0 && contractData.length === 0) {
      alert('先にデータを読み込んでください');
      return;
    }
    performAggregation();
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-export-csv').addEventListener('click', () => {
    if (aggregatedData.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }
    const headers = ['営業担当者', '売上高', '成約件数', '活動件数', '成約率'];
    const rows = aggregatedData.map(row => [
      row.userName,
      row.revenue,
      row.contractCount,
      row.activityCount,
      row.contractRate + '%'
    ]);
    const csv = '\uFEFF' + headers.join(',') + '\n' + rows.map(r => r.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '成果指標集計_' + new Date().toISOString().split('T')[0] + '.csv';
    link.click();
  });

  // ナビゲーションボタン
  container.querySelector('#btn-nav-template').addEventListener('click', () => {
    window.showScreen('scr-1781954055121');
  });

  container.querySelector('#btn-nav-generate').addEventListener('click', () => {
    window.showScreen('scr-1781954086842');
  });

  // 初期データ表示
  renderAggregateResults();
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=営業活動, 1=成約, 2=顧客企業, 3=レポートテンプレート, 4=生成済みレポート, 5=成果指標
  const activityTableIdx = 0;
  const contractTableIdx = 1;
  const customerTableIdx = 2;
  const templateTableIdx = 3;
  const reportTableIdx = 4;
  const metricTableIdx = 5;

  // 初期データを取得
  const activities = (tables[activityTableIdx]?.records || []);
  const contracts = (tables[contractTableIdx]?.records || []);
  const customers = (tables[customerTableIdx]?.records || []);
  const templates = (tables[templateTableIdx]?.records || []);
  const reports = (tables[reportTableIdx]?.records || []);
  const metrics = (tables[metricTableIdx]?.records || []);

  // ===== 1. レポート一覧再描画関数 =====
  function renderReports(reportRows) {
    const tbody = container.querySelector("#report-tbody");
    if (!reportRows || reportRows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="3" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px;">レポートがまだ生成されていません</td></tr>';
      return;
    }
    tbody.innerHTML = reportRows.map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 6px 4px; color: var(--text);">${r.レポートタイトル || r.report_title || '無名'}</td>
        <td style="padding: 6px 4px; color: var(--text-muted); font-size: 11px;">${r.生成日時 ? new Date(r.生成日時).toLocaleDateString('ja-JP') : '-'}</td>
        <td style="padding: 6px 4px; text-align: center;">
          <button class="action-btn secondary download-btn" data-id="${r.id}" style="padding: 3px 8px; font-size: 11px;">DL</button>
          <button class="action-btn secondary convert-btn" data-id="${r.id}" style="padding: 3px 8px; font-size: 11px; margin-left: 4px;">変換</button>
        </td>
      </tr>
    `).join("");
  }

  // ===== 2. プレビュー更新関数 =====
  function updatePreview() {
    const startDate = container.querySelector("#period-start").value;
    const endDate = container.querySelector("#period-end").value;
    const userId = container.querySelector("#user-select").value;
    const customerFilter = container.querySelector("#customer-filter").value.toLowerCase();

    // フィルタリング
    let filteredActivities = activities;
    let filteredContracts = contracts;

    if (startDate) {
      const start = new Date(startDate);
      filteredActivities = filteredActivities.filter(a => new Date(a.活動日 || a.activity_date) >= start);
      filteredContracts = filteredContracts.filter(c => new Date(c.成約日 || c.contract_date) >= start);
    }
    if (endDate) {
      const end = new Date(endDate);
      end.setHours(23, 59, 59, 999);
      filteredActivities = filteredActivities.filter(a => new Date(a.活動日 || a.activity_date) <= end);
      filteredContracts = filteredContracts.filter(c => new Date(c.成約日 || c.contract_date) <= end);
    }
    if (userId) {
      filteredActivities = filteredActivities.filter(a => a.ユーザーID === userId || a.user_id === userId);
      filteredContracts = filteredContracts.filter(c => c.ユーザーID === userId || c.user_id === userId);
    }
    if (customerFilter) {
      filteredActivities = filteredActivities.filter(a => (a.顧客名 || a.customer_name || '').toLowerCase().includes(customerFilter));
      filteredContracts = filteredContracts.filter(c => {
        const cust = customers.find(cu => cu.顧客企業ID === c.顧客企業ID || cu.customer_id === c.customer_id);
        return cust && (cust.企業名 || cust.company_name || '').toLowerCase().includes(customerFilter);
      });
    }

    // 統計計算
    const activityCount = filteredActivities.length;
    const contractCount = filteredContracts.length;
    const totalRevenue = filteredContracts.reduce((sum, c) => sum + (c.成約金額 || c.contract_amount || 0), 0);

    // プレビュー更新
    container.querySelector("[data-testid='preview-activities']").textContent = activityCount;
    container.querySelector("[data-testid='preview-orders']").textContent = contractCount;
    container.querySelector("[data-testid='preview-revenue']").textContent = `¥${totalRevenue.toLocaleString('ja-JP')}`;
  }

  // ===== 3. 初期描画 =====
  renderReports(reports);
  updatePreview();

  // ===== 4. イベントリスナー登録 =====
  // 期間・フィルタ変更時にプレビュー更新
  container.querySelector("#period-start").addEventListener("change", updatePreview);
  container.querySelector("#period-end").addEventListener("change", updatePreview);
  container.querySelector("#user-select").addEventListener("change", updatePreview);
  container.querySelector("#customer-filter").addEventListener("input", updatePreview);

  // レポート生成ボタン
  container.querySelector("#btn-generate").addEventListener("click", async () => {
    const startDate = container.querySelector("#period-start").value;
    const endDate = container.querySelector("#period-end").value;
    const userId = container.querySelector("#user-select").value;
    const templateId = container.querySelector("#template-select").value;
    const format = container.querySelector("input[name='format']:checked").value;
    const filename = container.querySelector("#filename-input").value || `report_${Date.now()}`;

    if (!startDate || !endDate || !templateId) {
      alert("期間とテンプレートを選択してください");
      return;
    }

    // 新規レポートを生成（API呼び出し）
    const newReport = {
      テンプレートID: templateId,
      ユーザーID: userId || null,
      レポート期間開始日: startDate,
      レポート期間終了日: endDate,
      生成日時: new Date().toISOString(),
      レポートタイトル: filename,
      レポート内容: `Generated report for ${startDate} to ${endDate}`,
      配信ステータス: "未配信",
      成約件数: contracts.filter(c => c.ユーザーID === userId || !userId).length,
      営業活動件数: activities.filter(a => a.ユーザーID === userId || !userId).length,
    };

    const saved = await window.aivicApi.save(reportTableIdx, newReport);
    if (saved) {
      // 生成済みレポート一覧を再取得して描画
      const updated = await window.aivicApi.list(reportTableIdx);
      renderReports(updated || []);
      alert(`レポートを生成しました: ${filename}.${format}`);
    }
  });

  // ダウンロードボタン
  container.addEventListener("click", async (e) => {
    const dlBtn = e.target.closest(".download-btn");
    if (dlBtn) {
      const reportId = dlBtn.dataset.id;
      const report = reports.find(r => r.id === reportId);
      if (report) {
        const format = container.querySelector("input[name='format']:checked").value;
        const filename = `${report.レポートタイトル || 'report'}.${format}`;
        // 実際のダウンロード処理（ここではシミュレーション）
        alert(`ダウンロード: ${filename}`);
      }
    }

    // 変換ボタン
    const cvtBtn = e.target.closest(".convert-btn");
    if (cvtBtn) {
      const reportId = cvtBtn.dataset.id;
      const report = reports.find(r => r.id === reportId);
      if (report) {
        const format = container.querySelector("input[name='format']:checked").value;
        const filename = `${report.レポートタイトル || 'report'}.${format}`;
        alert(`フォーマット変換: ${filename} (${format.toUpperCase()})`);
      }
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0 = 生成済みレポート
  const tableIndex = 0;
  let allReports = [];
  let selectedReport = null;

  // ===== 1. 再描画関数 =====
  function renderReports(reports) {
    const tbody = container.querySelector("#report-tbody");
    tbody.innerHTML = reports.map(r => {
      const statusColor = r.配信ステータス === "配信済み" ? "#ffd700" : 
                         r.配信ステータス === "配信失敗" ? "#dc143c" : "#999";
      const statusBg = r.配信ステータス === "配信済み" ? "rgba(255,215,0,0.15)" :
                      r.配信ステータス === "配信失敗" ? "rgba(220,20,60,0.15)" : "rgba(153,153,153,0.15)";
      return `
        <tr data-id="${r.レポートID}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s;">
          <td style="padding: 8px 10px; color: var(--text);">${r.レポートタイトル || ""}</td>
          <td style="padding: 8px 10px; text-align: center;">
            <span style="display: inline-block; padding: 3px 8px; border-radius: 3px; font-size: 11px; font-weight: 600; background: ${statusBg}; color: ${statusColor};">
              ${r.配信ステータス || "未配信"}
            </span>
          </td>
          <td style="padding: 8px 10px; text-align: center; color: var(--text-muted); font-size: 12px;">
            ${r.生成日時 ? new Date(r.生成日時).toLocaleDateString("ja-JP") : "-"}
          </td>
        </tr>
      `;
    }).join("");
  }

  // ===== 2. 初期データ読み込み =====
  window.aivicApi.list(tableIndex).then(rows => {
    allReports = rows || [];
    renderReports(allReports);
  });

  // ===== 3. フィルタ適用 =====
  container.querySelector("#btn-filter").addEventListener("click", () => {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const status = container.querySelector("#filter-status").value;
    const type = container.querySelector("#filter-type").value;

    const filtered = allReports.filter(r => {
      const rDate = new Date(r.生成日時);
      const start = startDate ? new Date(startDate) : new Date("2000-01-01");
      const end = endDate ? new Date(endDate) : new Date("2099-12-31");

      const dateOk = rDate >= start && rDate <= end;
      const statusOk = !status || r.配信ステータス === status;
      const typeOk = !type || r.レポート種別 === type;

      return dateOk && statusOk && typeOk;
    });

    renderReports(filtered);
  });

  // ===== 4. CSV出力 =====
  container.querySelector("#btn-export-csv").addEventListener("click", () => {
    if (allReports.length === 0) {
      showToast("エクスポートするレポートがありません");
      return;
    }

    const headers = ["レポートID", "レポートタイトル", "生成日時", "レポート種別", "配信ステータス", "成約件数", "売上金額"];
    const rows = allReports.map(r => [
      r.レポートID || "",
      r.レポートタイトル || "",
      r.生成日時 ? new Date(r.生成日時).toLocaleString("ja-JP") : "",
      r.レポート種別 || "",
      r.配信ステータス || "",
      r.成約件数 || 0,
      r.売上金額 || 0
    ]);

    const csv = "\uFEFF" + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(",")
    ).join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `reports_${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
    showToast("CSVをダウンロードしました");
  });

  // ===== 5. レポート選択 =====
  container.addEventListener("click", e => {
    const tr = e.target.closest("tbody tr");
    if (!tr) return;

    const reportId = tr.dataset.id;
    selectedReport = allReports.find(r => r.レポートID === reportId);

    if (!selectedReport) return;

    // UI更新
    container.querySelector("#detail-empty").style.display = "none";
    container.querySelector("#detail-header").style.display = "block";
    container.querySelector("#detail-preview").style.display = "block";
    container.querySelector("#detail-summary").style.display = "block";
    container.querySelector("#detail-actions").style.display = "flex";

    // 詳細表示
    container.querySelector("#detail-title").textContent = selectedReport.レポートタイトル || "";
    container.querySelector("#detail-generated").textContent = 
      selectedReport.生成日時 ? new Date(selectedReport.生成日時).toLocaleString("ja-JP") : "-";
    container.querySelector("#detail-type").textContent = selectedReport.レポート種別 || "-";

    const startDate = selectedReport.レポート期間開始日 ? new Date(selectedReport.レポート期間開始日).toLocaleDateString("ja-JP") : "";
    const endDate = selectedReport.レポート期間終了日 ? new Date(selectedReport.レポート期間終了日).toLocaleDateString("ja-JP") : "";
    container.querySelector("#detail-period").textContent = `${startDate} ～ ${endDate}`;

    // ステータスバッジ
    const badge = container.querySelector("#detail-status-badge");
    const statusText = selectedReport.配信ステータス || "未配信";
    const statusColor = statusText === "配信済み" ? "#ffd700" : 
                       statusText === "配信失敗" ? "#dc143c" : "#999";
    const statusBg = statusText === "配信済み" ? "rgba(255,215,0,0.15)" :
                    statusText === "配信失敗" ? "rgba(220,20,60,0.15)" : "rgba(153,153,153,0.15)";
    badge.textContent = statusText;
    badge.style.background = statusBg;
    badge.style.color = statusColor;

    const deliveredAt = container.querySelector("#detail-delivered-at");
    if (selectedReport.配信日時) {
      deliveredAt.textContent = `配信: ${new Date(selectedReport.配信日時).toLocaleString("ja-JP")}`;
    } else {
      deliveredAt.textContent = "";
    }

    // プレビュー
    container.querySelector("#preview-content").textContent = selectedReport.レポート内容 || "(内容なし)";

    // サマリー
    container.querySelector("#summary-contracts").textContent = (selectedReport.成約件数 || 0) + "件";
    container.querySelector("#summary-revenue").textContent = 
      "¥" + (selectedReport.売上金額 || 0).toLocaleString("ja-JP");
    container.querySelector("#summary-activities").textContent = 
      (selectedReport.営業活動件数 || 0) + "件";

    // 行ハイライト
    container.querySelectorAll("tbody tr").forEach(row => {
      row.style.background = row.dataset.id === reportId ? "rgba(255,215,0,0.1)" : "";
    });
  });

  // ===== 6. 配信実行 =====
  container.querySelector("#btn-deliver").addEventListener("click", () => {
    if (!selectedReport) return;

    const modal = container.querySelector("#modal-deliver");
    container.querySelector("#modal-deliver-to").textContent = 
      selectedReport.配信先メールアドレス || "(配信先未設定)";
    modal.style.display = "flex";
  });

  container.querySelector("#btn-modal-cancel").addEventListener("click", () => {
    container.querySelector("#modal-deliver").style.display = "none";
  });

  container.querySelector("#btn-modal-confirm").addEventListener("click", async () => {
    if (!selectedReport) return;

    container.querySelector("#modal-deliver").style.display = "none";

    // 配信ステータス更新
    const updated = await window.aivicApi.update(tableIndex, selectedReport.レポートID, {
      配信ステータス: "配信済み",
      配信日時: new Date().toISOString()
    });

    if (updated) {
      selectedReport.配信ステータス = "配信済み";
      selectedReport.配信日時 = new Date().toISOString();

      // UI再描画
      window.aivicApi.list(tableIndex).then(rows => {
        allReports = rows || [];
        renderReports(allReports);

        // 選択状態を復元
        const tr = container.querySelector(`tbody tr[data-id="${selectedReport.レポートID}"]`);
        if (tr) tr.click();
      });

      showToast("レポートを配信しました");
    } else {
      showToast("配信に失敗しました", "error");
    }
  });

  // ===== 7. 再配信 =====
  container.querySelector("#btn-resend").addEventListener("click", () => {
    if (!selectedReport) return;
    showToast("再配信機能は配信履歴画面から実行してください");
    // 実装: 配信履歴画面へ遷移
    // window.showScreen("scr-1781954135704");
  });

  // ===== 8. 配信履歴表示 =====
  container.querySelector("#btn-view-history").addEventListener("click", () => {
    if (!selectedReport) return;
    // 配信履歴画面へ遷移（レポートIDをパラメータで渡す）
    window.showScreen("scr-1781954135704");
  });

  // ===== ユーティリティ =====
  function showToast(message, type = "success") {
    const toast = container.querySelector("#toast");
    container.querySelector("#toast-message").textContent = message;
    toast.style.display = "block";
    toast.style.background = type === "error" ? "#dc143c" : "var(--primary)";
    setTimeout(() => {
      toast.style.display = "none";
    }, 3000);
  }
}

