        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 12px;">
          <div><span style="color: var(--text-muted);">売上高:</span> <span style="color: var(--text); font-weight: 600;">¥2,450,000</span></div>
          <div><span style="color: var(--text-muted);">受注件数:</span> <span style="color: var(--text); font-weight: 600;">12件</span></div>
          <div><span style="color: var(--text-muted);">営業活動:</span> <span style="color: var(--text); font-weight: 600;">45件</span></div>
          <div><span style="color: var(--text-muted);">成約率:</span> <span style="color: var(--text); font-weight: 600;">26.7%</span></div>
        </div>
      </div>
      <div style="font-size: 12px; color: var(--text-muted); line-height: 1.6;">
        <p>このレポートは選択されたテンプレートに基づいて自動生成されます。</p>
        <p>配信実行ボタンをクリックすると、指定された配信先に即座に配信されます。</p>
      </div>
    `;
    previewContent.innerHTML = preview;
  });

  // 6. リセットボタン
  container.querySelector("[data-testid='reset-form-btn']").addEventListener("click", () => {
    container.querySelector("[data-testid='template-select']").value = "";
    container.querySelector("[data-testid='delivery-method-select']").value = "";
    container.querySelector("[data-testid='period-start-input']").value = "";
    container.querySelector("[data-testid='period-end-input']").value = "";
    container.querySelector("[data-testid='target-users-input']").value = "";
    container.querySelector("[data-testid='metric-filter-select']").value = "";
    previewContent.innerHTML = '<p style="color: var(--text-muted);">配信設定を入力してプレビューボタンをクリックしてください</p>';
  });

  // 7. 配信実行ボタン
  container.querySelector("[data-testid='execute-delivery-btn']").addEventListener("click", async () => {
    const templateId = container.querySelector("[data-testid='template-select']").value;
    const deliveryMethod = container.querySelector("[data-testid='delivery-method-select']").value;
    const periodStart = container.querySelector("[data-testid='period-start-input']").value;
    const periodEnd = container.querySelector("[data-testid='period-end-input']").value;
    const targetUsers = container.querySelector("[data-testid='target-users-input']").value;

    if (!templateId || !deliveryMethod || !periodStart || !periodEnd || !targetUsers) {
      alert("すべての必須項目を入力してください");
      return;
    }

    const deliveryRecord = {
      生成済みレポートID: "rpt-" + Date.now(),
      配信先ユーザーID: targetUsers.split('\n')[0].trim(),
      配信先メールアドレス: targetUsers.split('\n')[0].trim(),
      配信日時: new Date().toISOString(),
      配信ステータス: "配信済み",
      配信方法: deliveryMethod,
      開封フラグ: false,
      再配信フラグ: false,
      再配信回数: 0
    };

    const saved = await window.aivicApi.save(3, deliveryRecord);
    if (saved) {
      alert("配信を実行しました");
      window.aivicApi.list(3).then(renderHistory);
      container.querySelector("[data-testid='reset-form-btn']").click();
    }
  });

  // 8. スケジュール登録ボタン
  container.querySelector("[data-testid='schedule-delivery-btn']").addEventListener("click", () => {
    scheduleModal.style.display = "flex";
  });

  // 9. モーダルキャンセル
  container.querySelector("[data-testid='modal-cancel-btn']").addEventListener("click", () => {
    scheduleModal.style.display = "none";
  });

  // 10. モーダル保存
  container.querySelector("[data-testid='modal-save-btn']").addEventListener("click", async () => {
    const scheduleName = container.querySelector("[data-testid='schedule-name-input']").value;
    const schedulePattern = container.querySelector("[data-testid='schedule-pattern-select']").value;
    const scheduleTime = container.querySelector("[data-testid='schedule-time-input']").value;
    const isEnabled = container.querySelector("[data-testid='schedule-enabled-checkbox']").checked;

    if (!scheduleName || !schedulePattern || !scheduleTime) {
      alert("すべての項目を入力してください");
      return;
    }

    const scheduleRecord = {
      テンプレート名: scheduleName,
      配信スケジュール: schedulePattern,
      配信時刻: scheduleTime,
      有効フラグ: isEnabled
    };

    const saved = await window.aivicApi.save(0, scheduleRecord);
    if (saved) {
      alert("スケジュールを登録しました");
      window.aivicApi.list(0).then(renderSchedules);
      scheduleModal.style.display = "none";
      container.querySelector("[data-testid='schedule-name-input']").value = "";
      container.querySelector("[data-testid='schedule-pattern-select']").value = "";
      container.querySelector("[data-testid='schedule-time-input']").value = "";
      container.querySelector("[data-testid='schedule-enabled-checkbox']").checked = false;
    }
  });

  // 11. 編集ボタン
  container.querySelector("[data-testid='edit-schedule-btn']").addEventListener("click", () => {
    if (!selectedScheduleId) {
      alert("編集するスケジュールを選択してください");
      return;
    }
    scheduleModal.style.display = "flex";
    // 選択されたスケジュールのデータをモーダルに読み込む処理（簡略版）
  });

  // 12. 削除ボタン
  container.querySelector("[data-testid='delete-schedule-btn']").addEventListener("click", async () => {
    if (!selectedScheduleId) {
      alert("削除するスケジュールを選択してください");
      return;
    }
    if (!confirm("このスケジュールを削除しますか？")) return;
    await window.aivicApi.delete(0, selectedScheduleId);
    window.aivicApi.list(0).then(renderSchedules);
    selectedScheduleId = null;
  });

  // 13. 履歴パネル折りたたみ
  toggleHistoryBtn.addEventListener("click", () => {
    isHistoryVisible = !isHistoryVisible;
    const historyPanel = toggleHistoryBtn.closest("div").parentElement;
    historyPanel.style.maxHeight = isHistoryVisible ? "200px" : "40px";
    toggleHistoryBtn.textContent = isHistoryVisible ? "▼ 隠す" : "▲ 表示";
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const reportTemplateIdx = tables.findIndex(t => t.tableName === 'レポートテンプレート') || 0;
  const generatedReportIdx = tables.findIndex(t => t.tableName === '生成済みレポート') || 1;

  // 初期データ
  const templates = tables[reportTemplateIdx]?.records || [];
  const generatedReports = tables[generatedReportIdx]?.records || [];

  // プレビュー生成関数
  function generatePreview() {
    const templateSelect = container.querySelector('#template-select');
    const periodStart = container.querySelector('#period-start');
    const periodEnd = container.querySelector('#period-end');
    const filterUser = container.querySelector('#filter-user');
    const filterCustomer = container.querySelector('#filter-customer');
    const metrics = Array.from(container.querySelectorAll('input[type="checkbox"]:checked'))
      .filter(cb => cb.id.startsWith('metric-'))
      .map(cb => cb.nextElementSibling?.textContent || cb.value);

    const templateName = templateSelect.options[templateSelect.selectedIndex]?.text || '未選択';
    const startDate = periodStart.value || '未指定';
    const endDate = periodEnd.value || '未指定';
    const userName = filterUser.options[filterUser.selectedIndex]?.text || '全員';
    const customerName = filterCustomer.options[filterCustomer.selectedIndex]?.text || '全社';

    const previewContent = container.querySelector('#preview-content');
    previewContent.innerHTML = `
      <div style="padding: 12px; background: rgba(0,0,0,0.1); border-radius: 4px;">
        <div style="margin-bottom: 12px; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 8px;">
          <div style="font-weight: 600; color: var(--primary); margin-bottom: 4px; font-size: 13px;">${templateName}</div>
          <div style="font-size: 11px; color: var(--text-muted);">期間: ${startDate} ～ ${endDate}</div>
        </div>
        <div style="margin-bottom: 12px;">
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">対象者: ${userName}</div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">顧客: ${customerName}</div>
        </div>
        <div style="margin-bottom: 12px; border-top: 1px solid rgba(255,255,255,0.1); padding-top: 8px;">
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; font-weight: 600;">含含める指標:</div>
          <div style="font-size: 11px; color: var(--text);">
            ${metrics.length > 0 ? metrics.join(', ') : '指標未選択'}
          </div>
        </div>
        <div style="background: rgba(0,0,0,0.2); padding: 8px; border-radius: 3px; font-size: 11px; color: var(--text-muted);">
          <div style="margin-bottom: 4px;">【サンプル統計】</div>
          <div>営業活動件数: 24件</div>
          <div>成約件数: 6件</div>
          <div>売上高: ¥2,400,000</div>
          <div>成約率: 25%</div>
        </div>
      </div>
    `;
  }

  // プレビューボタン
  container.querySelector('#btn-preview').addEventListener('click', generatePreview);

  // 生成・配信実行ボタン
  container.querySelector('#btn-generate').addEventListener('click', async () => {
    const templateSelect = container.querySelector('#template-select');
    const periodStart = container.querySelector('#period-start');
    const periodEnd = container.querySelector('#period-end');
    const scheduleFrequency = container.querySelector('#schedule-frequency');
    const reportFormat = container.querySelector('#report-format');
    const recipients = Array.from(container.querySelectorAll('input[id^="recipient-"]:checked'))
      .map(cb => cb.value);

    if (!templateSelect.value || !periodStart.value || !periodEnd.value || !scheduleFrequency.value || !reportFormat.value) {
      alert('必須項目を入力してください');
      return;
    }

    if (recipients.length === 0) {
      alert('配信先を選択してください');
      return;
    }

    // API呼び出し（生成済みレポート保存）
    const reportData = {
      テンプレートID: templateSelect.value,
      レポート期間開始日: periodStart.value,
      レポート期間終了日: periodEnd.value,
      配信スケジュール: scheduleFrequency.value,
      レポート形式: reportFormat.value,
      配信先ユーザー: recipients.join(','),
      配信ステータス: '配信済み',
      生成日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(generatedReportIdx, reportData);
    if (saved) {
      alert('レポートを生成・配信しました');
      // 履歴を更新
      const templateName = templateSelect.options[templateSelect.selectedIndex]?.text || 'レポート';
      const historyList = container.querySelector('#history-list');
      const newHistoryItem = document.createElement('div');
      newHistoryItem.style.cssText = 'padding: 8px; background: rgba(0,0,0,0.15); border-radius: 3px; margin-bottom: 6px;';
      newHistoryItem.innerHTML = `
        <div style="color: var(--text); margin-bottom: 2px;">${new Date().toLocaleDateString('ja-JP')} ${templateName}</div>
        <div style="color: var(--text-muted); font-size: 10px;">配信済み (${recipients.length}名)</div>
      `;
      historyList.insertBefore(newHistoryItem, historyList.firstChild);
    }
  });

  // フォーム入力時にプレビュー自動更新
  ['template-select', 'period-start', 'period-end', 'filter-user', 'filter-customer'].forEach(id => {
    const el = container.querySelector(`#${id}`);
    if (el) el.addEventListener('change', generatePreview);
  });

  Array.from(container.querySelectorAll('input[type="checkbox"]')).forEach(cb => {
    if (cb.id.startsWith('metric-')) {
      cb.addEventListener('change', generatePreview);
    }
  });

  // 初期プレビュー表示
  generatePreview();
}

function(container, apiUrl, tables) {
  // テーブルインデックス（仮定）
  const ACTIVITY_TABLE = 0;
  const DEAL_TABLE = 1;
  const TEMPLATE_TABLE = 2;
  const METRIC_TABLE = 3;

  // ========== 1. プレビューデータ再描画関数 ==========
  function renderActivityPreview(activities) {
    const tbody = container.querySelector("#activity-tbody");
    if (!activities || activities.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 8px; text-align: center; color: var(--text-muted); font-size: 11px;">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = activities.slice(0, 10).map(a => `
      <tr>
        <td style="padding: 6px; color: var(--text);">${a.活動日 ? new Date(a.活動日).toLocaleDateString('ja-JP') : '-'}</td>
        <td style="padding: 6px; color: var(--text);">${a.活動種別 || '-'}</td>
        <td style="padding: 6px; color: var(--text);">${a.顧客名 || '-'}</td>
        <td style="padding: 6px; text-align: right; color: var(--text);">¥${(a.成果金額 || 0).toLocaleString()}</td>
      </tr>
    `).join("");
  }

  function renderDealPreview(deals) {
    const tbody = container.querySelector("#deal-tbody");
    if (!deals || deals.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 8px; text-align: center; color: var(--text-muted); font-size: 11px;">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = deals.slice(0, 10).map(d => `
      <tr>
        <td style="padding: 6px; color: var(--text);">${d.成約日 ? new Date(d.成約日).toLocaleDateString('ja-JP') : '-'}</td>
        <td style="padding: 6px; color: var(--text);">${d.商品サービス名 || '-'}</td>
        <td style="padding: 6px; color: var(--text);">${d.顧客企業名 || '-'}</td>
        <td style="padding: 6px; text-align: right; color: var(--text);">¥${(d.成約金額 || 0).toLocaleString()}</td>
      </tr>
    `).join("");
  }

  // ========== 2. 初期データ描画 ==========
  if (tables[ACTIVITY_TABLE] && tables[ACTIVITY_TABLE].records) {
    renderActivityPreview(tables[ACTIVITY_TABLE].records);
  }
  if (tables[DEAL_TABLE] && tables[DEAL_TABLE].records) {
    renderDealPreview(tables[DEAL_TABLE].records);
  }

  // ========== 3. スケジュール種別の条件付き表示 ==========
  const scheduleTypeSelect = container.querySelector("#schedule-type");
  const scheduleDatetimeGroup = container.querySelector("#schedule-datetime-group");

  scheduleTypeSelect.addEventListener("change", (e) => {
    if (e.target.value === "scheduled") {
      scheduleDatetimeGroup.style.display = "block";
    } else {
      scheduleDatetimeGroup.style.display = "none";
    }
  });

  // ========== 4. プレビュー生成ボタン ==========
  container.querySelector("#btn-preview").addEventListener("click", async () => {
    const startDate = container.querySelector("#period-start").value;
    const endDate = container.querySelector("#period-end").value;
    const userId = container.querySelector("#target-user").value;
    const companyId = container.querySelector("#target-company").value;
    const templateId = container.querySelector("#template-select").value;

    // 指標チェック
    const metrics = [];
    if (container.querySelector("#metric-revenue").checked) metrics.push("売上高");
    if (container.querySelector("#metric-count").checked) metrics.push("受注件数");
    if (container.querySelector("#metric-activity").checked) metrics.push("営業活動件数");
    if (container.querySelector("#metric-conversion").checked) metrics.push("成約率");

    if (!startDate || !endDate || !userId || !templateId || metrics.length === 0) {
      alert("期間、対象ユーザー、テンプレート、指標を全て選択してください");
      return;
    }

    // データフィルタリング
    let activities = tables[ACTIVITY_TABLE]?.records || [];
    let deals = tables[DEAL_TABLE]?.records || [];

    if (startDate) {
      const start = new Date(startDate);
      activities = activities.filter(a => new Date(a.活動日) >= start);
      deals = deals.filter(d => new Date(d.成約日) >= start);
    }
    if (endDate) {
      const end = new Date(endDate);
      end.setHours(23, 59, 59);
      activities = activities.filter(a => new Date(a.活動日) <= end);
      deals = deals.filter(d => new Date(d.成約日) <= end);
    }
    if (userId) {
      activities = activities.filter(a => a.ユーザーID === userId);
      deals = deals.filter(d => d.ユーザーID === userId);
    }
    if (companyId) {
      deals = deals.filter(d => d.顧客企業ID === companyId);
    }

    // プレビュー再描画
    renderActivityPreview(activities);
    renderDealPreview(deals);

    // レポートプレビュー生成
    const totalRevenue = deals.reduce((sum, d) => sum + (d.成約金額 || 0), 0);
    const dealCount = deals.length;
    const activityCount = activities.length;
    const conversionRate = activityCount > 0 ? ((dealCount / activityCount) * 100).toFixed(1) : 0;

    let reportText = `【営業成果レポート】\n`;
    reportText += `期間: ${startDate} ～ ${endDate}\n`;
    reportText += `\n【成果指標】\n`;
    if (metrics.includes("売上高")) reportText += `売上高: ¥${totalRevenue.toLocaleString()}\n`;
    if (metrics.includes("受注件数")) reportText += `受注件数: ${dealCount}件\n`;
    if (metrics.includes("営業活動件数")) reportText += `営業活動件数: ${activityCount}件\n`;
    if (metrics.includes("成約率")) reportText += `成約率: ${conversionRate}%\n`;
    reportText += `\n【営業活動サマリー】\n`;
    reportText += `・訪問: ${activities.filter(a => a.活動種別 === "訪問").length}件\n`;
    reportText += `・電話: ${activities.filter(a => a.活動種別 === "電話").length}件\n`;
    reportText += `・メール: ${activities.filter(a => a.活動種別 === "メール").length}件\n`;
    reportText += `\n※このレポートは自動生成されました。`;

    container.querySelector("#report-preview").textContent = reportText;
  });

  // ========== 5. 即座配信ボタン ==========
  container.querySelector("#btn-deliver-now").addEventListener("click", async () => {
    const email = container.querySelector("#delivery-email").value;
    const reportText = container.querySelector("#report-preview").textContent;

    if (!email) {
      alert("配信先メールアドレスを入力してください");
      return;
    }
    if (reportText.includes("プレビュー生成ボタンをクリック")) {
      alert("先にプレビュー生成してください");
      return;
    }

    // 配信実行（API呼び出し）
    const deliveryData = {
      配信先メールアドレス: email,
      レポート内容: reportText,
      配信日時: new Date().toISOString(),
      配信ステータス: "配信済み"
    };

    const saved = await window.aivicApi.save(4, deliveryData); // 配信履歴テーブル
    if (saved) {
      alert("レポートを配信しました");
      container.querySelector("#delivery-email").value = "";
      container.querySelector("#report-preview").textContent = "プレビュー生成ボタンをクリックしてください";
    }
  });

  // ========== 6. スケジュール登録ボタン ==========
  container.querySelector("#btn-schedule-delivery").addEventListener("click", async () => {
    const email = container.querySelector("#delivery-email").value;
    const datetime = container.querySelector("#schedule-datetime").value;
    const reportText = container.querySelector("#report-preview").textContent;

    if (!email || !datetime) {
      alert("配信先メールアドレスと配信日時を入力してください");
      return;
    }
    if (reportText.includes("プレビュー生成ボタンをクリック")) {
      alert("先にプレビュー生成してください");
      return;
    }

    // スケジュール登録（API呼び出し）
    const scheduleData = {
      配信先メールアドレス: email,
      レポート内容: reportText,
      配信予定日時: datetime,
      配信ステータス: "予約済み"
    };

    const saved = await window.aivicApi.save(4, scheduleData);
    if (saved) {
      alert("レポート配信をスケジュール登録しました");
      container.querySelector("#delivery-email").value = "";
      container.querySelector("#schedule-datetime").value = "";
      container.querySelector("#report-preview").textContent = "プレビュー生成ボタンをクリックしてください";
    }
  });
}
